/* Abanico desplegable del hero: se despliega cuando cargan las capas del fondo (evento "hero:loaded"). */
(function(){
  var SRC="data:image/webp;base64,";
  var PIVOT={x:75,y:1075}, A0=-6, A1=100, N=12, OVERLAP=3, DURATION=1600;
  var ease=function(t){return t===1?1:1-Math.pow(2,-10*t)};
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var rad=function(d){return d*Math.PI/180}, step=(A1-A0)/N, sectors=[];
  for(var k=0;k<N;k++)sectors.push({s:k===0?-180:A0+k*step,e:k===N-1?270:A0+(k+1)*step+OVERLAP,o:k*step});
  document.querySelectorAll('canvas.abanico:not([data-ready])').forEach(function(canvas){
    canvas.setAttribute('data-ready','');
    var ctx=canvas.getContext('2d'), img=new Image(), p=0, W=900, H=1198;
    function draw(){var d=Math.min(window.devicePixelRatio||1,2);canvas.width=W*d;canvas.height=H*d;
      ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,W,H);ctx.globalAlpha=Math.min(1,p*1.6);
      sectors.forEach(function(x){ctx.save();ctx.translate(PIVOT.x,PIVOT.y);ctx.rotate(rad(-x.o*(1-p)));
        ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,2200,rad(x.s-90),rad(x.e-90));ctx.closePath();ctx.clip();
        ctx.drawImage(img,-PIVOT.x,-PIVOT.y,W,H);ctx.restore();});}
    function play(){var t0=performance.now();(function tick(n){var t=Math.min(1,(n-t0)/DURATION);p=ease(t);draw();if(t<1)requestAnimationFrame(tick);})(t0);}
    img.onload=function(){W=img.naturalWidth;H=img.naturalHeight;
      if(reduce){p=1;draw();return;}
      draw();if(document.querySelector('.hero.is-loaded'))play();else document.addEventListener('hero:loaded',play,{once:true});};
    img.src=SRC;
  });
})();
